// Loads the committed fixture runs (generated by the real CLI) for unit tests.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { Run, RunIndex } from '../../src/lib/types';

const root = fileURLToPath(new URL('../fixtures/', import.meta.url));

export function readFixture(path: string): unknown {
	return JSON.parse(readFileSync(root + path, 'utf8')) as unknown;
}

export function fixtureRun(asOf: '2026-11-03' | '2026-11-04'): Run {
	return readFixture(`runs/${asOf}.json`) as Run;
}

export function fixtureIndex(): RunIndex {
	return readFixture('runs/index.json') as RunIndex;
}
